CREATE DEFINER=`root`@`localhost` TRIGGER `trg_tb_payments_after_update` AFTER UPDATE ON `tb_payments` FOR EACH ROW BEGIN
    DECLARE v_campos TEXT;
    SET v_campos = CONCAT_WS(', ', IF(NOT (OLD.`ID` <=> NEW.`ID`), 'ID', NULL), IF(NOT (OLD.`order_ID` <=> NEW.`order_ID`), 'order_ID', NULL), IF(NOT (OLD.`user_payment_method_ID` <=> NEW.`user_payment_method_ID`), 'user_payment_method_ID', NULL), IF(NOT (OLD.`payment_method_ID` <=> NEW.`payment_method_ID`), 'payment_method_ID', NULL), IF(NOT (OLD.`installment_number` <=> NEW.`installment_number`), 'installment_number', NULL), IF(NOT (OLD.`installments_total` <=> NEW.`installments_total`), 'installments_total', NULL), IF(NOT (OLD.`due_date` <=> NEW.`due_date`), 'due_date', NULL), IF(NOT (OLD.`amount` <=> NEW.`amount`), 'amount', NULL), IF(NOT (OLD.`currency` <=> NEW.`currency`), 'currency', NULL), IF(NOT (OLD.`provider` <=> NEW.`provider`), 'provider', NULL), IF(NOT (OLD.`provider_reference` <=> NEW.`provider_reference`), 'provider_reference', NULL), IF(NOT (OLD.`payment_status` <=> NEW.`payment_status`), 'payment_status', NULL), IF(NOT (OLD.`creation_date` <=> NEW.`creation_date`), 'creation_date', NULL), IF(NOT (OLD.`paid_date` <=> NEW.`paid_date`), 'paid_date', NULL));
    IF v_campos <> '' THEN
        INSERT INTO tb_logs (table_name, record_ID, operation, db_user, db_role, description, old_values, new_values, operation_date, operation_status)
        VALUES ('tb_payments', CAST(NEW.`ID` AS CHAR), 'Update', USER(), (SELECT GROUP_CONCAT(DISTINCT re.FROM_USER ORDER BY re.FROM_USER SEPARATOR ', ') FROM mysql.role_edges re WHERE re.TO_USER = SUBSTRING_INDEX(USER(), '@', 1)),
            CONCAT('Registro actualizado en tb_payments. ID=', CAST(NEW.`ID` AS CHAR), ' | Campos: ', v_campos),
            JSON_MERGE_PRESERVE(JSON_OBJECT(), IF(NOT (OLD.`ID` <=> NEW.`ID`), JSON_OBJECT('ID', OLD.`ID`), JSON_OBJECT()), IF(NOT (OLD.`order_ID` <=> NEW.`order_ID`), JSON_OBJECT('order_ID', OLD.`order_ID`), JSON_OBJECT()), IF(NOT (OLD.`user_payment_method_ID` <=> NEW.`user_payment_method_ID`), JSON_OBJECT('user_payment_method_ID', OLD.`user_payment_method_ID`), JSON_OBJECT()), IF(NOT (OLD.`payment_method_ID` <=> NEW.`payment_method_ID`), JSON_OBJECT('payment_method_ID', OLD.`payment_method_ID`), JSON_OBJECT()), IF(NOT (OLD.`installment_number` <=> NEW.`installment_number`), JSON_OBJECT('installment_number', OLD.`installment_number`), JSON_OBJECT()), IF(NOT (OLD.`installments_total` <=> NEW.`installments_total`), JSON_OBJECT('installments_total', OLD.`installments_total`), JSON_OBJECT()), IF(NOT (OLD.`due_date` <=> NEW.`due_date`), JSON_OBJECT('due_date', OLD.`due_date`), JSON_OBJECT()), IF(NOT (OLD.`amount` <=> NEW.`amount`), JSON_OBJECT('amount', OLD.`amount`), JSON_OBJECT()), IF(NOT (OLD.`currency` <=> NEW.`currency`), JSON_OBJECT('currency', OLD.`currency`), JSON_OBJECT()), IF(NOT (OLD.`provider` <=> NEW.`provider`), JSON_OBJECT('provider', OLD.`provider`), JSON_OBJECT()), IF(NOT (OLD.`provider_reference` <=> NEW.`provider_reference`), JSON_OBJECT('provider_reference', OLD.`provider_reference`), JSON_OBJECT()), IF(NOT (OLD.`payment_status` <=> NEW.`payment_status`), JSON_OBJECT('payment_status', OLD.`payment_status`), JSON_OBJECT()), IF(NOT (OLD.`creation_date` <=> NEW.`creation_date`), JSON_OBJECT('creation_date', OLD.`creation_date`), JSON_OBJECT()), IF(NOT (OLD.`paid_date` <=> NEW.`paid_date`), JSON_OBJECT('paid_date', OLD.`paid_date`), JSON_OBJECT())),
            JSON_MERGE_PRESERVE(JSON_OBJECT(), IF(NOT (OLD.`ID` <=> NEW.`ID`), JSON_OBJECT('ID', NEW.`ID`), JSON_OBJECT()), IF(NOT (OLD.`order_ID` <=> NEW.`order_ID`), JSON_OBJECT('order_ID', NEW.`order_ID`), JSON_OBJECT()), IF(NOT (OLD.`user_payment_method_ID` <=> NEW.`user_payment_method_ID`), JSON_OBJECT('user_payment_method_ID', NEW.`user_payment_method_ID`), JSON_OBJECT()), IF(NOT (OLD.`payment_method_ID` <=> NEW.`payment_method_ID`), JSON_OBJECT('payment_method_ID', NEW.`payment_method_ID`), JSON_OBJECT()), IF(NOT (OLD.`installment_number` <=> NEW.`installment_number`), JSON_OBJECT('installment_number', NEW.`installment_number`), JSON_OBJECT()), IF(NOT (OLD.`installments_total` <=> NEW.`installments_total`), JSON_OBJECT('installments_total', NEW.`installments_total`), JSON_OBJECT()), IF(NOT (OLD.`due_date` <=> NEW.`due_date`), JSON_OBJECT('due_date', NEW.`due_date`), JSON_OBJECT()), IF(NOT (OLD.`amount` <=> NEW.`amount`), JSON_OBJECT('amount', NEW.`amount`), JSON_OBJECT()), IF(NOT (OLD.`currency` <=> NEW.`currency`), JSON_OBJECT('currency', NEW.`currency`), JSON_OBJECT()), IF(NOT (OLD.`provider` <=> NEW.`provider`), JSON_OBJECT('provider', NEW.`provider`), JSON_OBJECT()), IF(NOT (OLD.`provider_reference` <=> NEW.`provider_reference`), JSON_OBJECT('provider_reference', NEW.`provider_reference`), JSON_OBJECT()), IF(NOT (OLD.`payment_status` <=> NEW.`payment_status`), JSON_OBJECT('payment_status', NEW.`payment_status`), JSON_OBJECT()), IF(NOT (OLD.`creation_date` <=> NEW.`creation_date`), JSON_OBJECT('creation_date', NEW.`creation_date`), JSON_OBJECT()), IF(NOT (OLD.`paid_date` <=> NEW.`paid_date`), JSON_OBJECT('paid_date', NEW.`paid_date`), JSON_OBJECT())),
            NOW(), 1);
    END IF;
END;;

