CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_create_order`(
    IN  p_user_id  INT,
    OUT p_order_id INT UNSIGNED,
    OUT p_total    DECIMAL(12,3)
)
BEGIN
    DECLARE v_cart_id INT UNSIGNED DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    SELECT ID INTO v_cart_id
      FROM tb_carts
     WHERE user_ID = p_user_id AND cart_status = 'Active'
     LIMIT 1;

    IF v_cart_id IS NULL
       OR NOT EXISTS (SELECT 1 FROM tbd_cart_items WHERE cart_ID = v_cart_id) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El usuario no tiene un carrito activo con productos';
    END IF;

    IF EXISTS (SELECT 1 FROM tbd_cart_items ci
               JOIN tb_products p ON p.ID = ci.product_offer_ID
               WHERE ci.cart_ID = v_cart_id
                 AND (p.status = b'0' OR p.current_stock < ci.quantity)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Hay productos inactivos o sin stock suficiente';
    END IF;

    START TRANSACTION;

    INSERT INTO tb_orders (`key`, user_ID, cart_ID, total_products, total_cost, status_string)
    SELECT CONCAT('ORD-', DATE_FORMAT(NOW(), '%Y%m%d'), '-', UPPER(LEFT(REPLACE(UUID(), '-', ''), 8))),
           p_user_id, v_cart_id, SUM(ci.quantity), SUM(ci.quantity * p.current_price), 'Registered'
    FROM tbd_cart_items ci
    JOIN tb_products p ON p.ID = ci.product_offer_ID
    WHERE ci.cart_ID = v_cart_id;
    SET p_order_id = LAST_INSERT_ID();

    INSERT INTO tbd_order_items (order_ID, seller_ID, product_offer_ID, product_name, quantity, unit_price)
    SELECT p_order_id,
           (SELECT MIN(pr.user_ID) FROM tbd_products_users_providers pr
             WHERE pr.product_ID = p.ID AND pr.status = b'1'),
           p.ID, p.name, ci.quantity, p.current_price
    FROM tbd_cart_items ci
    JOIN tb_products p ON p.ID = ci.product_offer_ID
    WHERE ci.cart_ID = v_cart_id;

    UPDATE tb_products p
    JOIN tbd_cart_items ci ON ci.product_offer_ID = p.ID
       SET p.current_stock = p.current_stock - ci.quantity
     WHERE ci.cart_ID = v_cart_id;

    UPDATE tb_carts
       SET cart_status = 'Converted', converted_at = NOW()
     WHERE ID = v_cart_id;

    COMMIT;

    SELECT total_cost INTO p_total FROM tb_orders WHERE ID = p_order_id;
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_restore_product`(IN p_product_id INT UNSIGNED)
BEGIN
    IF NOT EXISTS (
        SELECT 1 
        FROM tb_products 
        WHERE ID = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;

    IF EXISTS (
        SELECT 1 
        FROM tb_products 
        WHERE ID = p_product_id 
          AND status = b'1'
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto ya se encuentra activo';
    END IF;

    UPDATE tb_products 
    SET status = b'1' 
    WHERE ID = p_product_id;
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_product`(IN p_product_id INT UNSIGNED)
BEGIN
    IF NOT EXISTS (
        SELECT 1 
        FROM tb_products 
        WHERE ID = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;

    IF EXISTS (
        SELECT 1 
        FROM tb_products 
        WHERE ID = p_product_id 
          AND status = b'0'
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto ya se encuentra eliminado';
    END IF;

    UPDATE tb_products 
    SET status = b'0' 
    WHERE ID = p_product_id;
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_user`(
    IN p_user_id INT UNSIGNED
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_db_user VARCHAR(32);
    DECLARE v_has_role INT DEFAULT 0;
    DECLARE v_exists INT DEFAULT 0;
    DECLARE v_status TINYINT DEFAULT NULL;
    DECLARE v_affected INT DEFAULT 0;

    -- 1. Identificar usuario de conexión
    SET v_db_user = SUBSTRING_INDEX(USER(), '@', 1);

    -- 2. Verificar roles autorizados asignados
    SELECT COUNT(*)
    INTO v_has_role
    FROM mysql.role_edges re
    WHERE re.TO_USER = v_db_user
      AND re.TO_HOST = '%'
      AND re.FROM_HOST = '%'
      AND re.FROM_USER IN (
          'superadmin',
          'admin',
          'support'
      );

    IF v_has_role = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'Acceso denegado: rol no autorizado';
    END IF;

    -- 3. Validar identificador
    IF p_user_id IS NULL OR p_user_id = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El identificador del usuario es inválido';
    END IF;

    -- 4. Comprobar existencia y estado
    SELECT COUNT(*), MAX(status + 0)
    INTO v_exists, v_status
    FROM tb_users
    WHERE ID = p_user_id;

    IF v_exists = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El usuario especificado no existe';
    END IF;

    -- 5. Comprobar estado actual
    IF v_status = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El usuario ya se encuentra inactivo';
    END IF;

    IF v_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'El usuario tiene un estado inválido';
    END IF;

    -- 6. Eliminación lógica
    UPDATE tb_users
    SET status = b'0'
    WHERE ID = p_user_id
      AND status = b'1';

    SET v_affected = ROW_COUNT();

    IF v_affected <> 1 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'No se pudo desactivar el usuario';
    END IF;

    -- 7. Confirmación
    SELECT
        'Usuario desactivado correctamente' AS mensaje,
        p_user_id AS user_id,
        v_db_user AS ejecutado_por,
        'Inactivo' AS estado_actual,
        CURRENT_TIMESTAMP AS fecha_operacion;

END ;;

